"""Single-host suite automation policies, planning, and governance metadata."""

from __future__ import annotations

from dataclasses import asdict, dataclass
from datetime import datetime, timedelta
import math
from typing import Any, Callable
import uuid


class AutomationConfigError(ValueError):
    """Raised when an automation policy is malformed or unsafe."""


@dataclass(frozen=True)
class BudgetLimits:
    """Hard upper bounds for API traffic generated by one suite run."""

    max_total_requests: int
    max_estimated_output_tokens: int


@dataclass(frozen=True)
class ApiPreflightPolicy:
    """Controls the optional API availability check before benchmark traffic."""

    enabled: bool
    timeout_seconds: float


@dataclass(frozen=True)
class AutomationPolicy:
    """Validated orchestration policy for one configured suite."""

    enabled: bool
    budget: BudgetLimits | None
    api_preflight: ApiPreflightPolicy
    max_total_duration_seconds: float | None


@dataclass(frozen=True)
class BudgetEstimate:
    """Conservative API traffic estimate derived from an expanded suite plan."""

    measurement_requests: int
    warmup_requests: int
    estimated_output_tokens: int
    conservative: bool

    @property
    def total_requests(self) -> int:
        """Return all estimated API requests, including warmup traffic."""
        return self.measurement_requests + self.warmup_requests

    def to_dict(self) -> dict[str, Any]:
        """Return a JSON-safe estimate representation."""
        return {
            "measurement_requests": self.measurement_requests,
            "warmup_requests": self.warmup_requests,
            "total_requests": self.total_requests,
            "estimated_output_tokens": self.estimated_output_tokens,
            "conservative": self.conservative,
        }


def parse_automation(value: Any) -> AutomationPolicy:
    """Parse and validate an optional root-level automation configuration.

    Args:
        value: The root-level ``automation`` object, or None.

    Returns:
        A validated automation policy. An omitted value returns a disabled policy.

    Raises:
        AutomationConfigError: If fields have invalid types, values, or shape.
    """
    if value is None:
        return AutomationPolicy(
            enabled=False,
            budget=None,
            api_preflight=ApiPreflightPolicy(enabled=False, timeout_seconds=5.0),
            max_total_duration_seconds=None,
        )
    if not isinstance(value, dict):
        raise AutomationConfigError("automation must be an object")
    unknown = sorted(
        set(value) - {"enabled", "budget", "api_preflight", "max_total_duration_seconds"}
    )
    if unknown:
        raise AutomationConfigError(
            f"automation has unknown fields: {', '.join(unknown)}"
        )
    enabled = value.get("enabled", True)
    if not isinstance(enabled, bool):
        raise AutomationConfigError("automation.enabled must be true or false")

    budget_value = value.get("budget")
    budget = _parse_budget(budget_value) if budget_value is not None else None
    if enabled and budget is None:
        raise AutomationConfigError(
            "automation.budget is required when automation.enabled is true"
        )

    preflight_value = value.get("api_preflight", {})
    if not isinstance(preflight_value, dict):
        raise AutomationConfigError("automation.api_preflight must be an object")
    unknown_preflight = sorted(set(preflight_value) - {"enabled", "timeout_seconds"})
    if unknown_preflight:
        raise AutomationConfigError(
            "automation.api_preflight has unknown fields: "
            f"{', '.join(unknown_preflight)}"
        )
    preflight_enabled = preflight_value.get("enabled", True)
    if not isinstance(preflight_enabled, bool):
        raise AutomationConfigError(
            "automation.api_preflight.enabled must be true or false"
        )
    timeout_seconds = preflight_value.get("timeout_seconds", 5.0)
    if not _positive_number(timeout_seconds):
        raise AutomationConfigError(
            "automation.api_preflight.timeout_seconds must be a positive number"
        )

    max_duration = value.get("max_total_duration_seconds")
    if max_duration is not None and not _positive_number(max_duration):
        raise AutomationConfigError(
            "automation.max_total_duration_seconds must be a positive number"
        )
    return AutomationPolicy(
        enabled=enabled,
        budget=budget,
        api_preflight=ApiPreflightPolicy(
            enabled=preflight_enabled,
            timeout_seconds=float(timeout_seconds),
        ),
        max_total_duration_seconds=float(max_duration) if max_duration is not None else None,
    )


def validate_immutable_report_target(policy: AutomationPolicy, target: str | None) -> None:
    """Require an immutable timestamp template for explicit automation reports.

    Args:
        policy: Validated automation policy.
        target: CLI-overridden or configured report target before replacement.

    Raises:
        AutomationConfigError: If an enabled policy uses an overwrite-prone target.
    """
    if policy.enabled and target is not None and "{timestamp}" not in target:
        raise AutomationConfigError(
            "automation requires report.path or --report to contain {timestamp}"
        )


def estimate_execution_plan(prepared: list[tuple[Any, Any, str, str]]) -> BudgetEstimate:
    """Estimate conservative API traffic before starting a suite.

    Args:
        prepared: Normalized suite entries of ``(case, args, scenario, case_key)``.

    Returns:
        An API-only measurement, warmup, and requested-output estimate. Sweep and
        SLO-capacity estimates are intentionally conservative upper bounds.
    """
    measurement_requests = 0
    warmup_requests = 0
    estimated_output_tokens = 0
    conservative = False
    for case, args, scenario, _ in prepared:
        if not case["enabled"] or args.mode != "api":
            continue
        measurement, warmup, output_tokens, case_conservative = _estimate_case(
            args, scenario
        )
        measurement_requests += measurement
        warmup_requests += warmup
        estimated_output_tokens += output_tokens
        conservative = conservative or case_conservative
    return BudgetEstimate(
        measurement_requests=measurement_requests,
        warmup_requests=warmup_requests,
        estimated_output_tokens=estimated_output_tokens,
        conservative=conservative,
    )


def budget_violation(
    estimate: BudgetEstimate, limits: BudgetLimits
) -> str | None:
    """Return a rejection reason when an estimate exceeds a configured limit."""
    if estimate.total_requests > limits.max_total_requests:
        return (
            f"estimated total requests {estimate.total_requests} exceeds "
            f"automation.budget.max_total_requests={limits.max_total_requests}"
        )
    if estimate.estimated_output_tokens > limits.max_estimated_output_tokens:
        return (
            "estimated requested output tokens "
            f"{estimate.estimated_output_tokens} exceeds "
            "automation.budget.max_estimated_output_tokens="
            f"{limits.max_estimated_output_tokens}"
        )
    return None


def preflight_api_targets(
    prepared: list[tuple[Any, Any, str, str]],
    policy: AutomationPolicy,
    request_get: Callable[..., Any],
) -> list[dict[str, Any]]:
    """Check each unique API target before benchmark traffic begins.

    Args:
        prepared: Normalized suite execution entries.
        policy: Validated automation policy.
        request_get: HTTP GET callable compatible with ``requests.get``.

    Returns:
        JSON-safe preflight records. A failed record includes ``outcome=failed``.
    """
    if not policy.enabled or not policy.api_preflight.enabled:
        return []

    targets: dict[tuple[str, str | None], Any] = {}
    for case, args, _, _ in prepared:
        if case["enabled"] and args.mode == "api":
            targets.setdefault((args.api_base.rstrip("/"), args.api_key), args)

    records = []
    for args in targets.values():
        url = f"{args.api_base.rstrip('/')}/models"
        headers = {"Content-Type": "application/json"}
        if args.api_key:
            headers["Authorization"] = f"Bearer {args.api_key}"
        try:
            response = request_get(
                url,
                headers=headers,
                timeout=policy.api_preflight.timeout_seconds,
            )
            status_code = getattr(response, "status_code", None)
            if not isinstance(status_code, int) or not 200 <= status_code < 300:
                raise RuntimeError(f"unexpected HTTP status {status_code!r}")
            payload = response.json()
            if not isinstance(payload, dict) or not isinstance(payload.get("data"), list):
                raise RuntimeError("response JSON must contain a data array")
            records.append({
                "api_base": args.api_base,
                "outcome": "passed",
                "status_code": status_code,
                "model_listed": any(
                    isinstance(item, dict) and item.get("id") == args.model
                    for item in payload["data"]
                ),
            })
        except Exception as exc:
            records.append({
                "api_base": args.api_base,
                "outcome": "failed",
                "error_type": type(exc).__name__,
                "message": str(exc),
            })
    return records


def build_run_governance(
    policy: AutomationPolicy,
    estimate: BudgetEstimate | None,
    plan_fingerprint: str,
    report_target: str,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Build run and provenance objects without secrets or expanded config data.

    Args:
        policy: Validated automation policy.
        estimate: Plan estimate when automation is enabled.
        plan_fingerprint: Safe execution-plan fingerprint.
        report_target: Resolved local path or S3 URI.

    Returns:
        A ``(run, provenance)`` tuple for inclusion in the JSON report.
    """
    run = {
        "id": str(uuid.uuid4()),
        "state": "running",
        "automation": {
            "enabled": policy.enabled,
            "budget": {
                "limits": asdict(policy.budget) if policy.budget else None,
                "estimate": estimate.to_dict() if estimate else None,
                "decision": "pending" if policy.enabled else "not_enabled",
            },
            "preflight": [],
            "deadline": {
                "max_total_duration_seconds": policy.max_total_duration_seconds,
                "started_at": None,
                "deadline_at": None,
                "exceeded_at": None,
            },
        },
    }
    provenance = {
        "execution_plan_sha256": plan_fingerprint,
        "report_target": report_target,
    }
    return run, provenance


def start_deadline(policy: AutomationPolicy) -> dict[str, str | None]:
    """Return serializable wall-clock deadline metadata for an accepted run."""
    started_at = datetime.now().astimezone()
    deadline_at = (
        started_at + timedelta(seconds=policy.max_total_duration_seconds)
        if policy.max_total_duration_seconds is not None else None
    )
    return {
        "started_at": started_at.isoformat(timespec="seconds"),
        "deadline_at": deadline_at.isoformat(timespec="seconds") if deadline_at else None,
    }


def _parse_budget(value: Any) -> BudgetLimits:
    """Parse required budget caps from an automation configuration."""
    if not isinstance(value, dict):
        raise AutomationConfigError("automation.budget must be an object")
    unknown = sorted(
        set(value) - {"max_total_requests", "max_estimated_output_tokens"}
    )
    if unknown:
        raise AutomationConfigError(
            f"automation.budget has unknown fields: {', '.join(unknown)}"
        )
    request_limit = value.get("max_total_requests")
    token_limit = value.get("max_estimated_output_tokens")
    if not _positive_int(request_limit):
        raise AutomationConfigError(
            "automation.budget.max_total_requests must be a positive integer"
        )
    if not _positive_int(token_limit):
        raise AutomationConfigError(
            "automation.budget.max_estimated_output_tokens must be a positive integer"
        )
    return BudgetLimits(
        max_total_requests=request_limit,
        max_estimated_output_tokens=token_limit,
    )


def _estimate_case(args: Any, scenario: str) -> tuple[int, int, int, bool]:
    """Return measurement requests, warmup requests, output tokens, conservatism."""
    if scenario == "pd-ratio":
        measurement = 16
        output_tokens = 8 + 8 * args.avg_output_tokens
        return measurement, 0, output_tokens, False

    if scenario in {"sweep", "slo-capacity-search"}:
        levels = list(range(1, args.sweep_max_concurrency + 1))
        if scenario == "sweep":
            levels = _powers_of_two(args.sweep_max_concurrency)
        requests_per_level = [
            args.sweep_requests_per_round or max(2 * concurrency, 4)
            for concurrency in levels
        ]
        measurement = sum(requests_per_level)
        if scenario == "slo-capacity-search":
            measurement *= args.slo_capacity_confirm_rounds
        output_limit = _output_limit(args)
        warmup = 0
        if not args.no_warmup:
            warmup = args.warmup_rounds * (args.warmup_requests_per_round or 1)
        return (
            measurement,
            warmup,
            measurement * output_limit + warmup * max(10, output_limit),
            True,
        )

    total_requests = max(args.num_prompts or args.concurrency, args.concurrency)
    if scenario == "mixed-workload":
        output_limit = max(
            int(part.split(":")[1]) for part in str(args.workload_mix).split(",")
        )
    else:
        output_limit = _output_limit(args)
    warmup = 0
    warmup_output_tokens = 0
    if not args.no_warmup:
        warmup = 1
        warmup_output_tokens = 10
        if args.random_prefix_len > 0 or args.share_prefix:
            warmup += args.warmup_rounds
            warmup_output_tokens += args.warmup_rounds
    return (
        total_requests,
        warmup,
        total_requests * output_limit + warmup_output_tokens,
        False,
    )


def _output_limit(args: Any) -> int:
    """Return the configured generation ceiling used for a request estimate."""
    if args.dataset == "random" and args.random_output_len is not None:
        return args.random_output_len
    return args.max_tokens


def _powers_of_two(maximum: int) -> list[int]:
    """Return powers of two up to and including a positive maximum."""
    values = []
    value = 1
    while value <= maximum:
        values.append(value)
        value *= 2
    return values


def _positive_int(value: Any) -> bool:
    """Return whether a value is a non-boolean positive integer."""
    return isinstance(value, int) and not isinstance(value, bool) and value > 0


def _positive_number(value: Any) -> bool:
    """Return whether a value is a finite, non-boolean positive number."""
    return (
        isinstance(value, (int, float))
        and not isinstance(value, bool)
        and math.isfinite(value)
        and value > 0
    )
